#!/usr/bin/env python3
# Writes src/builtin.inc, the C front end's catalogue of built-in
# functions, keywords and predefined preprocessor symbols, from the Go
# reference's internal/builtin (catalog_gen.go, generated by
# tools/mkbuiltin from the Icon sources, and gcon.go, gcon's additions).
# Functions and keywords are merged and sorted by name, as the Go's
# init does. Run from the repository root; needed only while the Go is
# the reference (the C will then generate the table from the Icon
# sources itself).
import re
gen = open('internal/builtin/catalog_gen.go').read()
gcon = open('internal/builtin/gcon.go').read()
S = r'("(?:[^"\\]|\\.)*")'
def funcs(src):
    out = []
    for m in re.finditer(r'\{Name: ' + S + r', Arity: (-?\d+), Signature: ' + S + r', Summary: ' + S + r'(?:, Graphics: (true|false))?(?:, Gcon: (true))?\}', src):
        out.append((m[1], m[2], m[3], m[4], m[5] == 'true', m[6] == 'true'))
    return out
def kws(src):
    out = []
    for m in re.finditer(r'\{Name: ' + S + r', Summary: ' + S + r'(?:, Gcon: (true))?\}', src):
        out.append((m[1], m[2], m[3] == 'true'))
    return out
def section(src, start):
    # from start to the closing brace of its list (at the start of a line,
    # or after a tab in gcon.go's var block)
    body = src[src.index(start):]
    return body[:re.search(r'^\t?\}$', body, re.M).start()]
fs = funcs(section(gen, 'var functions')) + funcs(section(gcon, 'gconFunctions'))
ks = kws(section(gen, 'var keywords')) + kws(section(gcon, 'gconKeywords'))
ps = re.findall(r'\{Name: ' + S + r', Feature: ' + S + r'\}', section(gen, 'var predefined'))
key = lambda t: eval(t[0]).encode()
fs.sort(key=key)
ks.sort(key=key)
b = lambda x: 'true' if x else 'false'
with open('src/builtin.inc', 'w') as f:
    f.write('/* Generated by src/tests/genbuiltin.py from the Go reference\'s\n'
            ' * internal/builtin (from the Icon sources, and gcon\'s additions). */\n\n')
    f.write('static const BuiltinFunc functions[] = {\n')
    for n, a, sig, summ, g, gc in fs:
        f.write('\t{%s, %s, %s, %s, %s, %s},\n' % (n, a, sig, summ, b(g), b(gc)))
    f.write('};\n\nstatic const Keyword keywords[] = {\n')
    for n, summ, gc in ks:
        f.write('\t{%s, %s, %s},\n' % (n, summ, b(gc)))
    f.write('};\n\nstatic const Predefined predefined[] = {\n')
    for n, feat in ps:
        f.write('\t{%s, %s},\n' % (n, feat))
    f.write('};\n')
print(len(fs), 'functions,', len(ks), 'keywords,', len(ps), 'predefined')
